<?= $this->extend('admin/layout') ?><?= $this->section('content') ?>
<div class="cms-content"><header class="cms-list-head"><div><h1>Enquiries</h1><p>Messages from buyers, farmers and potential partners.</p></div></header><?php if (! $inquiries): ?><section class="cms-card"><p class="cms-empty">There are no website enquiries yet.</p></section><?php else: ?><?php $selected = $inquiries[0]; ?><section class="cms-inbox"><aside class="cms-inbox-list"><div class="cms-inbox-list-head"><h2>All messages</h2></div><?php foreach ($inquiries as $inquiry): ?><a class="cms-inquiry-link" href="#message-<?= $inquiry['id'] ?>"><span class="cms-tag <?= strtolower($inquiry['subject']) === 'partnership' ? 'partner' : '' ?>"><?= esc($inquiry['subject']) ?></span><strong><?= esc($inquiry['message']) ?></strong><small><?= esc($inquiry['name']) ?><?= $inquiry['company'] ? ' · ' . esc($inquiry['company']) : '' ?> · <?= esc(date('d M', strtotime($inquiry['created_at']))) ?></small></a><?php endforeach ?></aside><article class="cms-inbox-detail" id="message-<?= $selected['id'] ?>"><div class="cms-detail-head"><div><span class="cms-tag"><?= esc($selected['subject']) ?></span><h1><?= esc($selected['name']) ?></h1><p class="from"><a href="mailto:<?= esc($selected['email']) ?>"><?= esc($selected['email']) ?></a><?= $selected['phone'] ? ' · ' . esc($selected['phone']) : '' ?><?= $selected['company'] ? ' · ' . esc($selected['company']) : '' ?></p></div><form class="cms-status-form" method="post" action="<?= site_url('admin/inquiries/' . $selected['id'] . '/status') ?>"><?= csrf_field() ?><select name="status"><option value="new" <?= $selected['status'] === 'new' ? 'selected' : '' ?>>New</option><option value="read" <?= $selected['status'] === 'read' ? 'selected' : '' ?>>In progress</option><option value="archived" <?= $selected['status'] === 'archived' ? 'selected' : '' ?>>Closed</option></select><button>Save</button></form></div><div class="cms-message"><?= nl2br(esc($selected['message'])) ?></div><small class="cms-time">Received <?= esc(date('d M Y, H:i', strtotime($selected['created_at']))) ?></small></article></section><?php endif ?></div>
<?= $this->endSection() ?>
